1	/**
2	 * CPython's `repr()` for `bytes` objects.
3	 *
4	 * `print(b'...')` goes through `str(bytes)`, which is `repr`, so this function
5	 * is what produces the program's entire stdout.
6	 */
7	
8	const BACKSLASH = 0x5c;
9	const SINGLE_QUOTE = 0x27;
10	const DOUBLE_QUOTE = 0x22;
11	const TAB = 0x09;
12	const NEWLINE = 0x0a;
13	const CARRIAGE_RETURN = 0x0d;
14	const SPACE = 0x20;
15	const DELETE = 0x7f;
16	
17	/**
18	 * Pick the delimiter CPython would use: a single quote unless the payload
19	 * contains a single quote but no double quote, in which case double quotes
20	 * avoid an escape.
21	 *
22	 * @param {Uint8Array} data
23	 * @returns {number} the quote byte
24	 */
25	function chooseQuote(data) {
26	  let hasSingle = false;
27	  let hasDouble = false;
28	  for (let i = 0; i < data.length; i += 1) {
29	    if (data[i] === SINGLE_QUOTE) hasSingle = true;
30	    else if (data[i] === DOUBLE_QUOTE) hasDouble = true;
31	  }
32	  return hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
33	}
34	
35	/**
36	 * Format a byte string exactly as `repr()` would, e.g.
37	 * `b'\xb7\x9c8@/\xabc\x8c\xf0@\xad\xec\xd3\xce\x81\t'`.
38	 *
39	 * @param {Uint8Array} data
40	 * @returns {string} ASCII-only representation
41	 */
42	export function reprBytes(data) {
43	  const quote = chooseQuote(data);
44	  const quoteChar = String.fromCharCode(quote);
45	  let out = `b${quoteChar}`;
46	
47	  for (let i = 0; i < data.length; i += 1) {
48	    const byte = data[i];
49	    if (byte === quote || byte === BACKSLASH) {
50	      out += `\\${String.fromCharCode(byte)}`;
51	    } else if (byte === TAB) {
52	      out += '\\t';
53	    } else if (byte === NEWLINE) {
54	      out += '\\n';
55	    } else if (byte === CARRIAGE_RETURN) {
56	      out += '\\r';
57	    } else if (byte < SPACE || byte >= DELETE) {
58	      out += `\\x${byte.toString(16).padStart(2, '0')}`;
59	    } else {
60	      out += String.fromCharCode(byte);
61	    }
62	  }
63	
64	  return out + quoteChar;
65	}
