19	 *       print(plaintext)
20	 *
21	 * Usage: node test13.mjs --key KEY --data DATA
22	 */
23	
24	import * as pyaes from './lib/aes/index.mjs';
25	import { ArgumentParser } from './lib/python/argparse.mjs';
26	import { programName, pythonArgv } from './lib/python/argv.mjs';
27	import { encodeUtf8Strict } from './lib/python/codecs.mjs';
28	import { PythonError } from './lib/python/exceptions.mjs';
29	import { addOuterFrame, frame } from './lib/python/frames.mjs';
30	import { reprBytes } from './lib/python/reprBytes.mjs';
31	import { print } from './lib/python/sys.mjs';
32	import { reportUnhandledException } from './lib/python/traceback.mjs';
33	
34	/** Identity of the original script, as it appears in tracebacks. */
35	const SCRIPT = 'test13.py';
36	const FROZEN_SCRIPT = 'test13';
37	
38	/**
39	 * Source lines of the original script, indent included.
40	 *
41	 * Only their geometry is used: the compiler records the byte offsets of each
42	 * failing sub-expression within its line, and the traceback renderer combines
43	 * those with whatever `test13.py` it can read from the working directory.
44	 */
45	const STATEMENTS = {
46	  moduleCall: { line: 18, text: '    main()' },
47	  init: {
48	    line: 11,
49	    text:
50	      '    aes = pyaes.AESModeOfOperationECB(args.key.encode())  # Initialize AES ECB cipher',
51	  },
52	  encrypt: {
53	    line: 12,
54	    text: '    ciphertext = aes.encrypt(args.data.encode())  # Encrypt plaintext',
55	  },
56	  decrypt: {
57	    line: 13,
58	    text: '    plaintext = aes.decrypt(ciphertext)  # Decrypt ciphertext back',
59	  },
60	};
61	
62	/**
63	 * Build the frame CPython would report for one sub-expression of a statement.
64	 *
65	 * @param {{line: number, text: string}} statement
66	 * @param {string} name enclosing function name
67	 * @param {string} expression the exact sub-expression being evaluated
68	 * @returns {object}
69	 */
70	function frameFor(statement, name, expression) {
71	  const colOffset = statement.text.indexOf(expression);
72	  return frame(SCRIPT, statement.line, name, {
73	    colOffset,
74	    endColOffset: colOffset + expression.length,
75	  });
76	}
77	
78	/**
79	 * Evaluate one sub-expression of `main`, tagging any Python-level exception
80	 * with the frame CPython would report for it.
81	 *
82	 * @template T
83	 * @param {{line: number, text: string}} statement
84	 * @param {string} expression the exact sub-expression being evaluated
85	 * @param {() => T} evaluate
86	 * @returns {T}
87	 */
88	function evaluated(statement, expression, evaluate) {
89	  try {
90	    return evaluate();
91	  } catch (error) {
92	    if (!(error instanceof PythonError)) throw error;
93	    throw addOuterFrame(error, frameFor(statement, 'main', expression));
94	  }
95	}
96	
97	/** Port of `main()`. */
98	function main() {
99	  const parser = new ArgumentParser({ prog: programName() });
100	  parser.addArgument(['--key'], { required: true }); // 16 bytes key
101	  parser.addArgument(['--data'], { required: true }); // 16 bytes data
102	  const args = parser.parseArgs(pythonArgv());
103	
104	  // Test round-trip encryption/decryption with ECB
105	  const key = evaluated(STATEMENTS.init, 'args.key.encode()', () =>
106	    encodeUtf8Strict(args.key),
107	  );
108	  const aes = evaluated(
109	    STATEMENTS.init,
110	    'pyaes.AESModeOfOperationECB(args.key.encode())',
111	    () => new pyaes.AESModeOfOperationECB(key), // Initialize AES ECB cipher
112	  );
113	
114	  const data = evaluated(STATEMENTS.encrypt, 'args.data.encode()', () =>
115	    encodeUtf8Strict(args.data),
116	  );
117	  const ciphertext = evaluated(
118	    STATEMENTS.encrypt,
119	    'aes.encrypt(args.data.encode())',
120	    () => aes.encrypt(data), // Encrypt plaintext
121	  );
122	
123	  const plaintext = evaluated(STATEMENTS.decrypt, 'aes.decrypt(ciphertext)', () =>
124	    aes.decrypt(ciphertext), // Decrypt ciphertext back
125	  );
126	
127	  print(reprBytes(ciphertext));
128	  print(reprBytes(plaintext));
129	}
130	
131	// if __name__ == '__main__': main()
132	try {
133	  main();
134	} catch (error) {
135	  if (!(error instanceof PythonError)) throw error;
136	  reportUnhandledException(
137	    addOuterFrame(error, frameFor(STATEMENTS.moduleCall, '<module>', 'main()')),
138	    FROZEN_SCRIPT,
139	  );
140	}
141	
142	export { main };
