1	/**
2	 * The slice of `sys` this program touches.
3	 *
4	 * Writes go out as raw bytes so nothing re-encodes the text on its way to the
5	 * pipe. On Linux, Node's writes to files, TTYs and pipes are all synchronous,
6	 * so output cannot be lost to a subsequent `process.exit`.
7	 */
8	
9	/**
10	 * `sys.stdout.write`
11	 *
12	 * @param {string} text
13	 */
14	export function writeStdout(text) {
15	  process.stdout.write(Buffer.from(text, 'utf8'));
16	}
17	
18	/**
19	 * `sys.stderr.write`
20	 *
21	 * @param {string} text
22	 */
23	export function writeStderr(text) {
24	  process.stderr.write(Buffer.from(text, 'utf8'));
25	}
26	
27	/**
28	 * `print(...)` for a single already-stringified argument.
29	 *
30	 * @param {string} text
31	 */
32	export function print(text) {
33	  writeStdout(`${text}\n`);
34	}
35	
36	/**
37	 * `sys.exit(status)`
38	 *
39	 * @param {number} status
40	 * @returns {never}
41	 */
42	export function exit(status) {
43	  process.exit(status);
44	}
45	
46	/**
47	 * The width argparse formats help against.
48	 *
49	 * `shutil.get_terminal_size()` prefers `$COLUMNS`, then the terminal, then
50	 * falls back to 80 columns — which is what happens whenever stdout is a pipe.
51	 *
52	 * @returns {number} total columns
53	 */
54	export function terminalColumns() {
55	  const fromEnvironment = Number.parseInt(process.env.COLUMNS ?? '', 10);
56	  if (Number.isInteger(fromEnvironment) && fromEnvironment > 0) return fromEnvironment;
57	  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
58	  return 80;
59	}
