1	#!/usr/bin/env node
2	/**
3	 * Differential harness: run the reference executable and the Node port with
4	 * identical argv, then compare stdout, exit status and (normalised) stderr.
5	 *
6	 * Usage: node diff.mjs <cases.jsonl> [--cwd <dir>] [--jobs N]
7	 *
8	 * Cases are JSON lines: {"name": "...", "args": [...], "env": {...}}.
9	 * An arg may be {"raw": "<bash $'...' body>"} for byte sequences a JS string
10	 * cannot carry.
11	 *
12	 * Exit status 0 = every case matched.
13	 */
14	
15	import { spawn } from 'node:child_process';
16	import { readFileSync } from 'node:fs';
17	
18	/**
19	 * The reference is invoked through a copy named `test13.mjs` so that argparse's
20	 * `prog` (basename of argv[0]) is identical on both sides — that turns the one
21	 * inherent divergence into an exact comparison of stdout AND stderr.
22	 * Pass --raw-reference to use the original name instead.
23	 */
24	const REFERENCE_COPY = '/tmp/refprog/test13.mjs';
25	const REFERENCE_ORIGINAL = '/workspace/dataset/test13_executable';
26	const PORT = ['node', '/output/test13.mjs'];
27	
28	const argv = process.argv.slice(2);
29	const casesPath = argv[0];
30	const option = (name, fallback) => {
31	  const at = argv.indexOf(name);
32	  return at === -1 ? fallback : argv[at + 1];
33	};
34	const workingDirectory = option('--cwd', process.cwd());
35	const jobs = Number(option('--jobs', '16'));
36	const rawReference = argv.includes('--raw-reference');
37	
38	if (!rawReference) {
39	  mkdirSync(dirname(REFERENCE_COPY), { recursive: true });
40	  copyFileSync(REFERENCE_ORIGINAL, REFERENCE_COPY);
41	  chmodSync(REFERENCE_COPY, 0o755);
42	}
43	const REFERENCE = [rawReference ? REFERENCE_ORIGINAL : REFERENCE_COPY];
44	
45	/** Only the bootloader's pid can never match; everything else must. */
46	const normalise = (text) => {
47	  const withoutPid = text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]');
48	  return rawReference
49	    ? withoutPid.replace(/test13_executable/g, '<prog>').replace(/test13\.mjs/g, '<prog>')
50	    : withoutPid;
51	};
52	
53	const shellQuote = (text) => `'${text.replace(/'/g, `'\\''`)}'`;
54	
55	/** Build a bash command that execs a program with possibly-raw byte args. */
56	function invocation(command, args) {
57	  const quoted = args.map((argument) =>
58	    typeof argument === 'object' && argument !== null && 'raw' in argument
59	      ? `$'${argument.raw}'`
60	      : shellQuote(String(argument)),
61	  );
62	  return `exec ${command.map(shellQuote).join(' ')} ${quoted.join(' ')}`;
63	}
64	
65	/** Run one program, collecting output as latin1 so bytes survive intact. */
66	function run(command, args, env) {
67	  return new Promise((resolve) => {
68	    const child = spawn('/bin/bash', ['-c', invocation(command, args)], {
69	      cwd: workingDirectory,
70	      env: { ...process.env, ...env },
71	    });
72	    const out = [];
73	    const err = [];
74	    child.stdout.on('data', (chunk) => out.push(chunk));
75	    child.stderr.on('data', (chunk) => err.push(chunk));
76	    child.on('close', (status) =>
77	      resolve({
78	        status,
79	        stdout: Buffer.concat(out).toString('latin1'),
80	        stderr: Buffer.concat(err).toString('latin1'),
81	      }),
82	    );
83	  });
84	}
85	
86	/** Compare one case; resolves to a failure report or null. */
87	async function check(testCase) {
88	  const env = testCase.env ?? {};
89	  const [expected, actual] = await Promise.all([
90	    run(REFERENCE, testCase.args, env),
91	    run(PORT, testCase.args, env),
92	  ]);
93	
94	  const problems = [];
95	  if (expected.stdout !== actual.stdout) problems.push('stdout');
96	  if (expected.status !== actual.status) problems.push('status');
97	  if (normalise(expected.stderr) !== normalise(actual.stderr)) problems.push('stderr');
98	  if (problems.length === 0) return null;
99	
100	  const report = [
101	    `FAIL [${problems.join(',')}] ${testCase.name ?? ''}`,
102	    `  args     : ${JSON.stringify(testCase.args)}`,
103	  ];
104	  if (Object.keys(env).length > 0) report.push(`  env      : ${JSON.stringify(env)}`);
105	  if (problems.includes('status')) {
106	    report.push(`  status   : want ${expected.status} got ${actual.status}`);
107	  }
108	  if (problems.includes('stdout')) {
109	    report.push(`  want out : ${JSON.stringify(expected.stdout)}`);
110	    report.push(`  got  out : ${JSON.stringify(actual.stdout)}`);
111	  }
112	  if (problems.includes('stderr')) {
113	    report.push(`  want err : ${JSON.stringify(normalise(expected.stderr))}`);
114	    report.push(`  got  err : ${JSON.stringify(normalise(actual.stderr))}`);
115	  }
116	  return report.join('\n');
117	}
118	
119	const cases = readFileSync(casesPath, 'utf8')
120	  .split('\n')
121	  .filter((line) => line.trim() !== '')
122	  .map((line) => JSON.parse(line));
123	
124	let failures = 0;
125	let next = 0;
126	
127	async function worker() {
128	  for (;;) {
129	    const index = next;
130	    next += 1;
131	    if (index >= cases.length) return;
132	    const failure = await check(cases[index]);
133	    if (failure !== null) {
134	      failures += 1;
135	      if (failures <= 30) console.log(failure);
136	    }
137	  }
138	}
139	
140	await Promise.all(Array.from({ length: Math.min(jobs, cases.length) }, worker));
141	
142	console.log(
143	  `\ncwd=${workingDirectory} checked ${cases.length} cases, ${failures} failures`,
144	);
145	process.exit(failures === 0 ? 0 : 1);
