// Independent transcription of CPython Objects/bytesobject.c:bytes_repr().
// Written from the C algorithm, deliberately NOT looking at the port.
export function cpythonBytesRepr(bytes) {
  let squotes = 0;
  let dquotes = 0;
  for (const b of bytes) {
    if (b === 0x27) squotes += 1;
    else if (b === 0x22) dquotes += 1;
  }
  let quote = 0x27; // single is preferred
  if (squotes && !dquotes) quote = 0x22;

  const parts = ['b', String.fromCharCode(quote)];
  for (const b of bytes) {
    if (b === quote || b === 0x5c) parts.push('\\' + String.fromCharCode(b));
    else if (b === 0x09) parts.push('\\t');
    else if (b === 0x0a) parts.push('\\n');
    else if (b === 0x0d) parts.push('\\r');
    else if (b === 0) parts.push('\\x00');
    else if (b < 0x20 || b >= 0x7f) {
      parts.push('\\x' + '0123456789abcdef'[(b & 0xf0) >> 4] + '0123456789abcdef'[b & 0xf]);
    } else parts.push(String.fromCharCode(b));
  }
  parts.push(String.fromCharCode(quote));
  return parts.join('');
}

// Exhaustively compare the port's reprBytes against the CPython oracle.
import { reprBytes } from '/output/lib/python/reprBytes.mjs';
import { cpythonBytesRepr } from './oracle.mjs';

let checked = 0;
const bad = [];

function check(arr) {
  const u = Uint8Array.from(arr);
  const want = cpythonBytesRepr(u);
  const got = reprBytes(u);
  checked += 1;
  if (want !== got && bad.length < 40) {
    bad.push({ bytes: Array.from(u), want, got });
  } else if (want !== got) {
    bad.push(null);
  }
}

// empty + every 1-byte value
check([]);
for (let a = 0; a < 256; a += 1) check([a]);

// every ordered 2-byte pair (65536)
for (let a = 0; a < 256; a += 1) for (let b = 0; b < 256; b += 1) check([a, b]);

// every byte in leading / middle / trailing position of a 16-byte block
for (let v = 0; v < 256; v += 1) {
  for (const pos of [0, 7, 15]) {
    const arr = new Array(16).fill(0x41);
    arr[pos] = v;
    check(arr);
  }
}

// every byte value crossed with the four quote populations, in 3 positions
const populations = [[], [0x27], [0x22], [0x27, 0x22], [0x22, 0x27], [0x27, 0x27], [0x22, 0x22]];
for (let v = 0; v < 256; v += 1) {
  for (const pop of populations) {
    check([v, ...pop]);
    check([...pop, v]);
    check([pop[0] ?? 0x41, v, ...pop.slice(1)]);
  }
}

// every 3-byte combination drawn from the interesting alphabet
const alphabet = [
  0x00, 0x01, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x1f, 0x20, 0x22, 0x27, 0x5c, 0x5d,
  0x7e, 0x7f, 0x80, 0x81, 0x8f, 0x90, 0x9f, 0xa0, 0xc0, 0xc1, 0xf5, 0xfe, 0xff,
];
for (const a of alphabet)
  for (const b of alphabet) for (const c of alphabet) check([a, b, c]);

console.log(`checked ${checked} inputs, ${bad.length} mismatches`);
for (const m of bad.slice(0, 40)) {
  if (m) console.log(JSON.stringify(m));
}
process.exit(bad.length === 0 ? 0 : 1);

// Race-free differential harness for the bytes-repr audit.
// Cases: {name, key: <byte array>, data: <byte array>}
// Compares reference vs port (stdout/stderr/status) AND validates the
// CPython-repr oracle against the reference's second output line.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { cpythonBytesRepr } from './oracle.mjs';

const REFERENCE = ['/tmp/br/ref/test13.mjs'];
const PORT = ['node', '/output/test13.mjs'];

const bashBytes = (arr) =>
  "$'" + Array.from(arr, (b) => '\\x' + b.toString(16).padStart(2, '0')).join('') + "'";
const shellQuote = (t) => `'${t.replace(/'/g, `'\\''`)}'`;

function run(command, key, data) {
  const cmd = `exec ${command.map(shellQuote).join(' ')} --key ${bashBytes(key)} --data ${bashBytes(data)}`;
  return new Promise((resolve) => {
    const child = spawn('/bin/bash', ['-c', cmd], { cwd: '/tmp/br' });
    const out = [];
    const err = [];
    child.stdout.on('data', (c) => out.push(c));
    child.stderr.on('data', (c) => err.push(c));
    child.on('close', (status) =>
      resolve({
        status,
        stdout: Buffer.concat(out).toString('latin1'),
        stderr: Buffer.concat(err).toString('latin1'),
      }),
    );
  });
}

const normalise = (t) => t.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]');

const cases = readFileSync(process.argv[2], 'utf8')
  .split('\n')
  .filter((l) => l.trim())
  .map((l) => JSON.parse(l));

let failures = 0;
let oracleFailures = 0;
let next = 0;
const seenCipherBytes = new Set();
const seenCipherPos = new Map(); // "pos:byte"
const reports = [];

async function worker() {
  for (;;) {
    const i = next++;
    if (i >= cases.length) return;
    const c = cases[i];
    const [want, got] = await Promise.all([
      run(REFERENCE, c.key, c.data),
      run(PORT, c.key, c.data),
    ]);
    const problems = [];
    if (want.stdout !== got.stdout) problems.push('stdout');
    if (want.status !== got.status) problems.push('status');
    if (normalise(want.stderr) !== normalise(got.stderr)) problems.push('stderr');
    if (problems.length && reports.length < 25) {
      reports.push(
        [
          `FAIL [${problems.join(',')}] ${c.name}`,
          `  key      : ${JSON.stringify(c.key)}`,
          `  data     : ${JSON.stringify(c.data)}`,
          `  status   : want ${want.status} got ${got.status}`,
          `  want out : ${JSON.stringify(want.stdout)}`,
          `  got  out : ${JSON.stringify(got.stdout)}`,
          `  want err : ${JSON.stringify(normalise(want.stderr))}`,
          `  got  err : ${JSON.stringify(normalise(got.stderr))}`,
        ].join('\n'),
      );
    }
    if (problems.length) failures += 1;

    // Oracle validation + ciphertext byte coverage, only for clean runs.
    if (want.status === 0) {
      const lines = want.stdout.split('\n');
      const oracleSecond = cpythonBytesRepr(Uint8Array.from(c.data));
      if (lines[1] !== oracleSecond) {
        oracleFailures += 1;
        if (reports.length < 25)
          reports.push(
            `ORACLE MISMATCH ${c.name}\n  data ${JSON.stringify(c.data)}\n  ref  ${JSON.stringify(lines[1])}\n  orac ${JSON.stringify(oracleSecond)}`,
          );
      }
      // recover ciphertext bytes by inverting the repr of line 0
      const ct = decodeRepr(lines[0]);
      if (ct) {
        ct.forEach((b, pos) => {
          seenCipherBytes.add(b);
          seenCipherPos.set(`${pos}:${b}`, true);
        });
      }
    }
  }
}

/** Invert a bytes repr back to bytes (validates the reference's own output). */
function decodeRepr(text) {
  if (!text || text[0] !== 'b') return null;
  const q = text[1];
  const body = text.slice(2, -1);
  const out = [];
  for (let i = 0; i < body.length; i += 1) {
    if (body[i] !== '\\') {
      out.push(body.charCodeAt(i));
      continue;
    }
    const n = body[i + 1];
    if (n === 'x') {
      out.push(parseInt(body.slice(i + 2, i + 4), 16));
      i += 3;
    } else if (n === 't') { out.push(9); i += 1; }
    else if (n === 'n') { out.push(10); i += 1; }
    else if (n === 'r') { out.push(13); i += 1; }
    else { out.push(body.charCodeAt(i + 1)); i += 1; }
  }
  return out;
}

await Promise.all(Array.from({ length: Math.min(24, cases.length) }, worker));

