// Search key/data pairs whose CIPHERTEXT exercises each repr feature, using the
// port's AES only as a search oracle; every hit is then re-verified against the
// frozen reference binary.
import { writeFileSync } from 'node:fs';
import { AESModeOfOperationECB } from '/output/lib/aes/modes.mjs';

const printable = (n, seed) => {
  let s = seed;
  const out = [];
  for (let i = 0; i < n; i += 1) {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    out.push(0x21 + ((s >>> 9) % 0x5e));
  }
  return out;
};

const wants = {
  'ct-single-only': (c) => c.includes(0x27) && !c.includes(0x22),
  'ct-double-only': (c) => c.includes(0x22) && !c.includes(0x27),
  'ct-both-quotes': (c) => c.includes(0x27) && c.includes(0x22),
  'ct-backslash': (c) => c.includes(0x5c),
  'ct-backslash-and-single': (c) => c.includes(0x5c) && c.includes(0x27) && !c.includes(0x22),
  'ct-tab': (c) => c.includes(0x09),
  'ct-newline': (c) => c.includes(0x0a),
  'ct-cr': (c) => c.includes(0x0d),
  'ct-nul-first': (c) => c[0] === 0x00,
  'ct-nul-last': (c) => c[15] === 0x00,
  'ct-nul-mid': (c) => c[7] === 0x00,
  'ct-7f': (c) => c.includes(0x7f),
  'ct-ff-first': (c) => c[0] === 0xff,
  'ct-ff-last': (c) => c[15] === 0xff,
  'ct-80': (c) => c.includes(0x80),
  'ct-1f': (c) => c.includes(0x1f),
  'ct-0b0c': (c) => c.includes(0x0b) || c.includes(0x0c),
  'ct-quote-first': (c) => c[0] === 0x27,
  'ct-quote-last': (c) => c[15] === 0x27,
  'ct-dquote-first': (c) => c[0] === 0x22,
  'ct-backslash-last': (c) => c[15] === 0x5c,
  'ct-nul-and-quote': (c) => c.includes(0x00) && c.includes(0x27),
  'ct-tab-and-quote': (c) => c.includes(0x09) && c.includes(0x27) && !c.includes(0x22),
};
const found = new Map();
const target = 3; // a few witnesses each

for (let n = 0; n < 400000 && found.size < Object.keys(wants).length * target; n += 1) {
  const key = printable(16, 0x1234 + n * 7919);
  const data = printable(16, 0x99991 + n * 104729);
  const ct = Array.from(new AESModeOfOperationECB(Uint8Array.from(key)).encrypt(Uint8Array.from(data)));
  for (const [name, pred] of Object.entries(wants)) {
    for (let k = 0; k < target; k += 1) {
      const id = `${name}#${k}`;
      if (!found.has(id) && pred(ct) && ![...found.keys()].some((e) => e.startsWith(name + '#') && found.get(e).ctKey === ct.join(','))) {
        found.set(id, { name: id, key, data, ctKey: ct.join(',') });
        break;
      }
    }
  }
}

const missing = Object.keys(wants).filter((n) => !found.has(`${n}#0`));
console.log(`found ${found.size} witnesses; unmatched predicates: ${missing.join(',') || 'none'}`);
writeFileSync(
  process.argv[2],
  [...found.values()].map((c) => JSON.stringify({ name: c.name, key: c.key, data: c.data })).join('\n') + '\n',
);

